import { MakeLogicType, connect, kea, key, path, props } from 'kea'
import { loaders } from 'kea-loaders'

import { projectLogic } from 'scenes/projectLogic'

import { tasksRetrieve, tasksUsageRetrieve } from 'products/tasks/frontend/generated/api'
import { TaskOriginProductEnumApi } from 'products/tasks/frontend/generated/api.schemas'

export interface TaskComputeCostLogicProps {
    taskId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taskComputeCostLogicValues {
    currentProjectId: number | null // projectLogic
    computeCostUsd: number
    computeCostUsdLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taskComputeCostLogicActions {
    loadComputeCost: () => any
    loadComputeCostFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadComputeCostSuccess: (
        computeCostUsd: number,
        payload?: any
    ) => {
        computeCostUsd: number
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taskComputeCostLogicMeta {
    key: string
}

export type taskComputeCostLogicType = MakeLogicType<
    taskComputeCostLogicValues,
    taskComputeCostLogicActions,
    TaskComputeCostLogicProps,
    taskComputeCostLogicMeta
>

// PostHog Desktop bills the compute of these origins on its own meter and shows it there. The usage
// endpoint reports compute for any other origin only when AI_CREDITS_COMPUTE_BILLED_ORIGINS bills that
// origin into AI credits, so skipping these keeps the chip on the AI credits setting alone.
const DESKTOP_BILLED_ORIGINS = new Set<string>([TaskOriginProductEnumApi.UserCreated, 'space_setup'])

/** The billed sandbox compute of a task in USD, which the agent's own usage frames do not know about. */
export const taskComputeCostLogic = kea<taskComputeCostLogicType>([
    path((key) => ['products', 'posthog_ai', 'frontend', 'logics', 'taskComputeCostLogic', key]),
    props({} as TaskComputeCostLogicProps),
    key((props) => props.taskId),
    connect(() => ({ values: [projectLogic, ['currentProjectId']] })),
    loaders(({ props, values, cache }) => ({
        computeCostUsd: [
            0,
            {
                loadComputeCost: async (_, breakpoint) => {
                    // A history replay marks every past turn complete at once, so wait for the burst to end.
                    await breakpoint(500)
                    const projectId = String(values.currentProjectId)
                    if (cache.originProduct === undefined) {
                        cache.originProduct = (await tasksRetrieve(projectId, props.taskId)).origin_product
                        breakpoint()
                    }
                    if (DESKTOP_BILLED_ORIGINS.has(cache.originProduct)) {
                        return 0
                    }
                    const usage = await tasksUsageRetrieve(projectId, props.taskId)
                    breakpoint()
                    return usage.compute_cost_usd
                },
            },
        ],
    })),
])
